[{"order":1,"type":"heading","text":"Component Lifecycle Hooks in Vue 3"},{"order":2,"type":"paragraph","text":"Understanding the component lifecycle is essential for building robust applications in Vue 3. Lifecycle hooks allow you to execute code at specific stages of a component's existence, from creation to destruction."},{"order":3,"type":"subheading","text":"Introduction to Composition API Lifecycle Hooks"},{"order":4,"type":"paragraph","text":"With the introduction of the Composition API in Vue 3, lifecycle hooks are now imported as functions and can be called inside the setup() function or <script setup> block. Unlike the Options API, Vue 3 hooks are prefixed with "on"."},{"order":5,"type":"bullet_point","text":"onMounted: Called after the component has been mounted to the DOM."},{"order":6,"type":"bullet_point","text":"onUpdated: Called after a reactive state change has caused the DOM to patch."},{"order":7,"type":"bullet_point","text":"onUnmounted: Called after the component has been unmounted and destroyed."},{"order":8,"type":"subheading","text":"Code Example: Using Lifecycle Hooks"},{"order":9,"type":"code","text":"<script setup>
import { ref, onMounted, onUnmounted } from 'vue';

const count = ref(0);
let timer = null;

onMounted(() => {
  console.log('Component is mounted!');
  timer = setInterval(() => {
    count.value++;
  }, 1000);
});

onUnmounted(() => {
  console.log('Component is unmounted. Cleaning up timer...');
  clearInterval(timer);
});
</script>"},{"order":10,"type":"subheading","text":"Best Practices"},{"order":11,"type":"bullet_point","text":"Always clean up side effects like timers, event listeners, and subscriptions inside onUnmounted to prevent memory leaks."},{"order":12,"type":"bullet_point","text":"Prefer onMounted over created (which is replaced by setup itself) for DOM manipulation tasks."}]
